import std.io

fn identity<T>(x: T) -> T {
    return x
}

fn pair2<A, B>(a: A, b: B) -> (A, B) {
    return (a, b)
}

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = identity(3)
    let b = identity<Float64>(1.5)
    let c = pair2(1, "x")
    let (n, s) = c
    io.println("${a} ${b} ${n}${s}")
    return Ok(())
}
